--
-- Name: insert_user_for_messages(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.insert_user_for_messages() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    session_variables json;
BEGIN
    session_variables := current_setting('hasura.user', 't');
        VALUES (
            (session_variables->>'x-hasura-user-id'),
            (session_variables->>'x-hasura-email')
        )
        ON CONFLICT ON CONSTRAINT users_name_key DO NOTHING;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.insert_user_for_messages() OWNER TO postgres;

--
-- Name: set_current_timestamp_deleted_at(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_current_timestamp_deleted_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  _new record;
BEGIN
  _new := NEW;
  _new."deleted_at" = NOW();
  RETURN _new;
END;
$$;


ALTER FUNCTION public.set_current_timestamp_deleted_at() OWNER TO postgres;

--
-- Name: set_current_timestamp_updated_at(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_current_timestamp_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.set_current_timestamp_updated_at() OWNER TO postgres;

